#  ★제목: 시리즈 틀(229 districts·Age-standardized) 금지, 쌍점 금지, 발견형. 미국식 철자(JCL). 단독 저자 무인칭. Results 숫자만, Discussion 숫자 없음.
#  ★역방향 결과(공공체육시설 +, 수검률 +): 부호·주분석 불변, 사전 가설(−)과 반대였음을 명시, 발견 효과는 '양립'으로만, 인과·정책 함의 금지. 격차 작음(P90/P10 1.22) 과장 금지.
import os, json
HERE = os.path.dirname(os.path.abspath(__file__)); N = json.load(open(os.path.join(HERE, "numbers_lips.json")))
def th(x, d=0): return f"{x:,.{d}f}"
def ci(k, src="main", lab=True):
    e, lo, hi = (N[src][k] if isinstance(src, str) else src)
    return f"{e:.3f} (95% CrI {lo:.3f}-{hi:.3f})" if lab else f"{e:.3f} ({lo:.3f}-{hi:.3f})"
def tc(k, src): return ci(k, src, False)
def ph(a, c): return tc(None, N["ph"][f"{a}|{c}"])
def cs(k, src="main"):
    e, lo, hi = (N[src][k] if isinstance(src, str) else src); return f"RR {e:.3f}; 95% CrI {lo:.3f}-{hi:.3f}"
def pct(x): return f"{100 * x:.0f}%"
R = N["rate"]; RA = N["rate_aux"]; HC = N["hc"]; MV = N["mv"]; PH = N["ph"]
SF, UP = "ext__public_sport_fac_per100k", "ext__screening_uptake"
def rng(k, srcs): v = [N[s][k][0] for s in srcs]; return f"{min(v):.3f}-{max(v):.3f}"
KHS = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
TITLE = "Suspected dyslipidemia at Korean health screening is modestly higher in the southwest and rises with screening uptake within districts"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
KEYWORDS = "Dyslipidemias; Mass screening; Undiagnosed disease; Physical activity; Small-area analysis; Spatio-temporal analysis; Republic of Korea"
RUNNING = "Suspected dyslipidemia at screening in Korea"
GH, GC = N["gi_hot_sido"], N["gi_cold_sido"]
hot_jj = GH.get("Jeonnam", 0) + GH.get("Jeonbuk", 0); cold_gd = GC.get("Gyeongbuk", 0) + GC.get("Daegu", 0)

ABSTRACT = [
("Background", "Korean general health screening labels attendees with abnormal lipid results who are not already treated as having suspected dyslipidemia."),
("Objective", "To describe where suspected dyslipidemia is more common than expected across Korean districts and whether physical activity, lipid risk behaviors, and screening and care reach are associated with it."),
("Methods", f"This ecological panel study covered {N['n_districts']} districts from 2018 to 2024 ({N['cases_total_m']:.2f} million suspected judgements among {N['exam_total_m']:.1f} million examinations). Expected counts were standardized for sex and 15 age groups. Bayesian spatio-temporal negative binomial models related counts to 10 district characteristics with 5 adjustments, with covariate subsets, space-time interactions, lags, and comparison outcomes."),
("Results", f"District standardized ratios ranged from {N['sir_p10']:.2f} to {N['sir_p90']:.2f} (10th-90th percentile); {hot_jj} of {N['gi_hot']} hot spots lay in Jeonnam and Jeonbuk and {cold_gd} of {N['gi_cold']} cold spots in Gyeongbuk and Daegu. Contrary to the expected direction, screening uptake was positively associated (principal model {cs('screening_uptake')} per 1 SD; {rng('screening_uptake', KHS)} across Knorr-Held models), within districts over time but not between districts, not for treated dyslipidemia, and with uncertainty when 2020-2021 were excluded. Public sports facilities were also positively associated ({cs('public_sport_fac')}), an estimate that weakened with province-by-year effects. Walking and moderate physical activity showed no consistent association."),
("Conclusions", "Suspected dyslipidemia at screening was modestly higher in southwestern districts. It rose in years when a district's screening uptake rose, compatible with case finding, but this small association and that of sports facilities may reflect residual confounding."),
]

INTRO = [
"Non-optimal cholesterol remains a leading modifiable cause of atherosclerotic cardiovascular disease, and over recent decades its global center has moved from north-western Europe towards east and south-east Asia [@ncdrisc2020repositioning]. Lowering low-density lipoprotein cholesterol reduces major vascular events in proportion to the reduction achieved [@ctt2010efficacy], and Korean guidelines recommend treatment according to total cardiovascular risk [@rhee2019guidelines].",
"In Korea, the prevalence of hypercholesterolemia rose between 2007 and 2022 while awareness and treatment improved [@kwon2025dyslipidemia; @lee2025national]. Gaps remain: in 2008-2010, fewer than 1 in 10 adults younger than 50 years with high low-density lipoprotein cholesterol knew of it [@lee2014serum], and among Korean patients with dyslipidemia, cardiovascular risk and statin prescription have been reported to differ by region [@han2021regional2; @han2021regional].",
"Korea's national general health screening offers a direct view of untreated dyslipidemia. The National Health Insurance Service, which runs the program, holds the screening records of the insured population [@cheolseong2017data], and the published statistics label each examinee whose lipid results exceed the judgement criteria and who does not report current treatment as having suspected dyslipidemia, count those already treated separately, and are released every year by district, sex, and age [@web:kosis2026screening]. Attending screening has been associated with fewer atherosclerotic events [@suh2017impact], but in 2003-2011 fewer than 1 in 8 examinees with hypercholesterolemia newly detected at screening, even when it persisted at the next screening, received a statin [@ahn2015treatment]. A district count of suspected dyslipidemia therefore reflects both how common untreated dyslipidemia is and whom screening reaches.",
"Area characteristics could shape both parts. Exercise training raises high-density lipoprotein cholesterol and lowers triglycerides modestly [@kodama2007effect; @smart2025effect]; in a Canadian cross-sectional study, residents of more walkable neighborhoods had lower triglycerides and higher high-density lipoprotein cholesterol [@cakmak2024association]; and in Gyeonggi Province, adults aged 60 years or older living farther from public physical-activity facilities had higher odds of self-reported physician-diagnosed dyslipidemia [@lee2021objectively]. Obesity and smoking are associated with adverse lipid profiles, and moderate drinking raises high-density lipoprotein cholesterol and triglycerides [@vekic2019obesity; @craig1989cigarette; @rimm1999moderate]. Screening attendance and medical care determine whether dyslipidemia is first found at screening or already treated.",
"To the author's knowledge, no study has mapped suspected dyslipidemia at screening across all Korean districts or asked whether its geography follows physical activity, lipid risk behaviors, or the reach of screening and care. This study used 7 years of national screening statistics under the current lipid testing schedule to describe where suspected dyslipidemia is more common than expected after standardization for sex and age, and to examine its association with district characteristics, contrasting it with dyslipidemia that was already treated.",
]

METHODS = [
("Study design and data",
 f"This ecological panel study covered all {N['n_districts']} districts (si, gun, and gu) of the Republic of Korea from 2018 to 2024 ({th(N['n_rows'])} district-years). The outcome was the annual number of examinees judged at the first stage of the National Health Insurance Service general health screening to have suspected dyslipidemia, that is, lipid results above the judgement criteria without a reported diagnosis under treatment; examinees already treated for dyslipidemia are reported as a separate category [@web:kosis2026screening]. The denominator was the number of examinees with a judgement result. Sejong, reported only at the province level, was included as 1 district. In 2018, the lipid test changed from every 2 years for all adults to every 4 years for men aged 24 years or older and women aged 40 years or older [@web:yonhap2023screening], and the national share of examinees with suspected dyslipidemia fell from {RA['2017']:.1f}% in 2017 to {R['2018']:.1f}% in 2018. Because the lipid test is scheduled by sex and age, examinees without a test in a given year remain in the denominator; age- and sex-specific national rates absorb this schedule in the expected counts. The main analysis therefore used 2018-2024, and 2011-2017 was analyzed separately. Districts were linked by administrative codes. The outcome was chosen among screening indicators because its standardized ratio showed spatial clustering and a stable ranking, and the covariate sets were fixed before modeling.",
 "Expected counts were obtained by indirect standardization [@inskip1983methods]. National rates of suspected dyslipidemia among examinees in 2 sexes and 15 age groups (19 years or younger, 13 five-year groups from 20-24 to 80-84 years, and 85 years or older) were applied to the examinee age structure of each district, approximated from the resident population by sex and age [@web:mois2026population] and national age-specific screening rates and rescaled to the observed number of examinees of each sex. Expected counts were rescaled each year so that national expected and observed totals matched. The ratio of observed to expected counts is the standardized ratio."),
("District characteristics",
 "Ten characteristics were examined in 3 groups, with directions set before modeling (Supplementary Table S1). Physical activity was represented by the age-standardized walking and moderate-or-higher physical activity rates from the Community Health Survey [@kang2015korea] and by public and village sports facilities per 100,000 residents (expected lower counts). Lipid risk behaviors were represented by the survey's self-reported obesity, high-risk drinking, and current smoking rates (expected higher counts). Screening and care reach were represented by screening uptake (attendees as a share of those invited), internal medicine specialists per 100,000 residents, and the public assistance recipient rate (uptake and specialists expected to lower, and deprivation to raise, counts of untreated dyslipidemia). All models included 5 fixed adjustments: urban population share, physicians per 1,000 residents, sex ratio, fiscal autonomy, and the share aged 80 years or older. Survey items not collected in 2019 were interpolated within districts, and implausibly low or high public assistance values in 2021-2023 were set to missing and interpolated. Hit-and-run crashes, a traffic culture index, and fires served as negative-control exposures [@lipsitch2010negative]."),
("Statistical analysis",
 f"Counts were modeled with a negative binomial likelihood, chosen over the Poisson by the widely applicable information criterion (WAIC) in models with the fixed adjustments only [@gelman2014understanding], with the log of expected counts as the offset, a Besag-York-Mollié 2 district effect on a contact graph of 593 neighboring pairs [@besag1991bayesian; @riebler2016intuitive], and first-order random-walk and independent year effects. Penalized complexity priors were used (probability 0.01 that a standard deviation exceeds 0.5; probability 2/3 that the spatial mixing parameter is below 0.5) [@simpson2017penalising]. Characteristics were standardized to 1 SD and reported as rate ratios (RRs) with 95% credible intervals (CrIs); an association was credible when the CrI excluded 1. Models were fitted with integrated nested Laplace approximation [@rue2009approximate] in R 4.6.0 [@web:rcore2026]. Hot and cold spots of the 7-year ratio were identified with the Getis-Ord Gi* statistic on the same graph including each district itself (P < .05, without correction for multiple testing) [@ord1995local], and stability with yearly Moran's I and Kendall's W. Descriptive statistics and the principal model were also reported for 2018-2019 and 2020-2024.",
 "Robustness was assessed in 5 prespecified ways. First, 200 models used random subsets of the 10 characteristics, always with the 5 adjustments [@steegen2016increasing]; a characteristic was subset-stable when its CrI excluded 1 in at least 75% of subsets containing it with at least 95% sign agreement. Second, Knorr-Held space-time interaction types I-IV were added [@knorrheld2000bayesian]. Third, Spatial+ [@dupont2022spatial], province-by-year random effects, characteristics lagged by 1 and 2 years, alternative district effects (intrinsic conditional autoregressive, independent, or none), and a Poisson-lognormal likelihood were fitted. Fourth, the principal model was refitted with 2 comparison outcomes from the same screening statistics, standardized in the same way: examinees already treated for dyslipidemia and examinees with suspected diabetes. Fifth, the model was refitted with a 577-pair queen contiguity graph, without the age-80 adjustment, with unstandardized expected counts, and for 2011-2017. E-values were computed for credible associations [@vanderweele2017sensitivity]. After the results were seen, the 2 associations opposite to the expected direction were examined with additional models: between-district means and within-district deviations [@bell2015explaining], population density, sports facilities per area or log-transformed, single-characteristic models, education, unmet medical need and older adults living alone, and exclusion of 2020-2021. Reporting followed STROBE [@vonelm2007strengthening], and sex was handled as recorded in the statistics (male or female) through standardization [@heidari2016sex].",
 "The Institutional Review Board of Hongik University approved the study on November 4, 2025 (7002340-202511-HR-012) and its continuing review on November 3, 2026 (7002340-202611-HR-040), and waived informed consent because only published aggregate statistics were used."),
]

def gi_list(d, order):
    parts = [f"{d[k]} in {k}" for k in order if k in d] + [f"{v} in {k}" for k, v in d.items() if k not in order]
    return ", ".join(parts[:-1]) + ", and " + parts[-1]
